macro_rules! deps {
    () => {
        EndianRcSlice!();
        Format!();
        Result!();
        Reference!();
        EndianSlice!();
        ReaderOffsetId!();
        ReaderOffset!();
        Error!();
        Endianity!();
    };
}

macro_rules! Reader {
    () => {
        deps!();
        # [doc = " A trait for reading the data from a DWARF section."] # [doc = ""] # [doc = " All read operations advance the section offset of the reader"] # [doc = " unless specified otherwise."] # [doc = ""] # [doc = " ## Choosing a `Reader` Implementation"] # [doc = ""] # [doc = " `gimli` comes with a few different `Reader` implementations and lets you"] # [doc = " choose the one that is right for your use case. A `Reader` is essentially a"] # [doc = " view into the raw bytes that make up some DWARF, but this view might borrow"] # [doc = " the underlying data or use reference counting ownership, and it might be"] # [doc = " thread safe or not."] # [doc = ""] # [doc = " | Implementation    | Ownership         | Thread Safe | Notes |"] # [doc = " |:------------------|:------------------|:------------|:------|"] # [doc = " | [`EndianSlice`](./struct.EndianSlice.html)        | Borrowed          | Yes         | Fastest, but requires that all of your code work with borrows. |"] # [doc = " | [`EndianRcSlice`](./struct.EndianRcSlice.html)    | Reference counted | No          | Shared ownership via reference counting, which alleviates the borrow restrictions of `EndianSlice` but imposes reference counting increments and decrements. Cannot be sent across threads, because the reference count is not atomic. |"] # [doc = " | [`EndianArcSlice`](./struct.EndianArcSlice.html)  | Reference counted | Yes         | The same as `EndianRcSlice`, but uses atomic reference counting, and therefore reference counting operations are slower but `EndianArcSlice`s may be sent across threads. |"] # [doc = " | [`EndianReader<T>`](./struct.EndianReader.html)   | Same as `T`       | Same as `T` | Escape hatch for easily defining your own type of `Reader`. |"] pub trait Reader : Debug + Clone { # [doc = " The endianity of bytes that are read."] type Endian : Endianity ; # [doc = " The type used for offsets and lengths."] type Offset : ReaderOffset ; # [doc = " Return the endianity of bytes that are read."] fn endian (& self) -> Self :: Endian ; # [doc = " Return the number of bytes remaining."] fn len (& self) -> Self :: Offset ; # [doc = " Set the number of bytes remaining to zero."] fn empty (& mut self) ; # [doc = " Set the number of bytes remaining to the specified length."] fn truncate (& mut self , len : Self :: Offset) -> Result < () > ; # [doc = " Return the offset of this reader's data relative to the start of"] # [doc = " the given base reader's data."] # [doc = ""] # [doc = " May panic if this reader's data is not contained within the given"] # [doc = " base reader's data."] fn offset_from (& self , base : & Self) -> Self :: Offset ; # [doc = " Return an identifier for the current reader offset."] fn offset_id (& self) -> ReaderOffsetId ; # [doc = " Return the offset corresponding to the given `id` if"] # [doc = " it is associated with this reader."] fn lookup_offset_id (& self , id : ReaderOffsetId) -> Option < Self :: Offset > ; # [doc = " Find the index of the first occurrence of the given byte."] # [doc = " The offset of the reader is not changed."] fn find (& self , byte : u8) -> Result < Self :: Offset > ; # [doc = " Discard the specified number of bytes."] fn skip (& mut self , len : Self :: Offset) -> Result < () > ; # [doc = " Split a reader in two."] # [doc = ""] # [doc = " A new reader is returned that can be used to read the next"] # [doc = " `len` bytes, and `self` is advanced so that it reads the remainder."] fn split (& mut self , len : Self :: Offset) -> Result < Self > ; # [doc = " This trait cannot be implemented if \"read\" feature is not enabled."] # [doc = ""] # [doc = " `Reader` trait has a few methods that depend on `alloc` crate."] # [doc = " Disallowing `Reader` trait implementation prevents a crate that only depends on"] # [doc = " \"read-core\" from being broken if another crate depending on `gimli` enables"] # [doc = " \"read\" feature."] # [cfg (not (feature = "read"))] fn cannot_implement () -> seal_if_no_alloc :: Sealed ; # [doc = " Return all remaining data as a clone-on-write slice."] # [doc = ""] # [doc = " The slice will be borrowed where possible, but some readers may"] # [doc = " always return an owned vector."] # [doc = ""] # [doc = " Does not advance the reader."] # [cfg (feature = "read")] fn to_slice (& self) -> Result < Cow < '_ , [u8] > > ; # [doc = " Convert all remaining data to a clone-on-write string."] # [doc = ""] # [doc = " The string will be borrowed where possible, but some readers may"] # [doc = " always return an owned string."] # [doc = ""] # [doc = " Does not advance the reader."] # [doc = ""] # [doc = " Returns an error if the data contains invalid characters."] # [cfg (feature = "read")] fn to_string (& self) -> Result < Cow < '_ , str > > ; # [doc = " Convert all remaining data to a clone-on-write string, including invalid characters."] # [doc = ""] # [doc = " The string will be borrowed where possible, but some readers may"] # [doc = " always return an owned string."] # [doc = ""] # [doc = " Does not advance the reader."] # [cfg (feature = "read")] fn to_string_lossy (& self) -> Result < Cow < '_ , str > > ; # [doc = " Read exactly `buf.len()` bytes into `buf`."] fn read_slice (& mut self , buf : & mut [u8]) -> Result < () > ; # [doc = " Read a u8 array."] # [inline] fn read_u8_array < A > (& mut self) -> Result < A > where A : Sized + Default + AsMut < [u8] > , { let mut val = Default :: default () ; self . read_slice (< A as AsMut < [u8] > > :: as_mut (& mut val)) ? ; Ok (val) } # [doc = " Return true if the number of bytes remaining is zero."] # [inline] fn is_empty (& self) -> bool { self . len () == Self :: Offset :: from_u8 (0) } # [doc = " Read a u8."] # [inline] fn read_u8 (& mut self) -> Result < u8 > { let a : [u8 ; 1] = self . read_u8_array () ? ; Ok (a [0]) } # [doc = " Read an i8."] # [inline] fn read_i8 (& mut self) -> Result < i8 > { let a : [u8 ; 1] = self . read_u8_array () ? ; Ok (a [0] as i8) } # [doc = " Read a u16."] # [inline] fn read_u16 (& mut self) -> Result < u16 > { let a : [u8 ; 2] = self . read_u8_array () ? ; Ok (self . endian () . read_u16 (& a)) } # [doc = " Read an i16."] # [inline] fn read_i16 (& mut self) -> Result < i16 > { let a : [u8 ; 2] = self . read_u8_array () ? ; Ok (self . endian () . read_i16 (& a)) } # [doc = " Read a u32."] # [inline] fn read_u32 (& mut self) -> Result < u32 > { let a : [u8 ; 4] = self . read_u8_array () ? ; Ok (self . endian () . read_u32 (& a)) } # [doc = " Read an i32."] # [inline] fn read_i32 (& mut self) -> Result < i32 > { let a : [u8 ; 4] = self . read_u8_array () ? ; Ok (self . endian () . read_i32 (& a)) } # [doc = " Read a u64."] # [inline] fn read_u64 (& mut self) -> Result < u64 > { let a : [u8 ; 8] = self . read_u8_array () ? ; Ok (self . endian () . read_u64 (& a)) } # [doc = " Read a u128."] # [inline] fn read_u128 (& mut self) -> Result < u128 > { let a : [u8 ; 16] = self . read_u8_array () ? ; Ok (self . endian () . read_u128 (& a)) } # [doc = " Read an i64."] # [inline] fn read_i64 (& mut self) -> Result < i64 > { let a : [u8 ; 8] = self . read_u8_array () ? ; Ok (self . endian () . read_i64 (& a)) } # [doc = " Read a f32."] # [inline] fn read_f32 (& mut self) -> Result < f32 > { let a : [u8 ; 4] = self . read_u8_array () ? ; Ok (self . endian () . read_f32 (& a)) } # [doc = " Read a f64."] # [inline] fn read_f64 (& mut self) -> Result < f64 > { let a : [u8 ; 8] = self . read_u8_array () ? ; Ok (self . endian () . read_f64 (& a)) } # [doc = " Read an unsigned n-bytes integer u64."] # [doc = ""] # [doc = " # Panics"] # [doc = ""] # [doc = " Panics when nbytes < 1 or nbytes > 8"] # [inline] fn read_uint (& mut self , n : usize) -> Result < u64 > { let mut buf = [0 ; 8] ; self . read_slice (& mut buf [.. n]) ? ; Ok (self . endian () . read_uint (& buf [.. n])) } # [doc = " Read a null-terminated slice, and return it (excluding the null)."] fn read_null_terminated_slice (& mut self) -> Result < Self > { let idx = self . find (0) ? ; let val = self . split (idx) ? ; self . skip (Self :: Offset :: from_u8 (1)) ? ; Ok (val) } # [doc = " Skip a LEB128 encoded integer."] fn skip_leb128 (& mut self) -> Result < () > { leb128 :: read :: skip (self) } # [doc = " Read an unsigned LEB128 encoded integer."] fn read_uleb128 (& mut self) -> Result < u64 > { leb128 :: read :: unsigned (self) } # [doc = " Read an unsigned LEB128 encoded u32."] fn read_uleb128_u32 (& mut self) -> Result < u32 > { leb128 :: read :: unsigned (self) ? . try_into () . map_err (| _ | Error :: BadUnsignedLeb128) } # [doc = " Read an unsigned LEB128 encoded u16."] fn read_uleb128_u16 (& mut self) -> Result < u16 > { leb128 :: read :: u16 (self) } # [doc = " Read a signed LEB128 encoded integer."] fn read_sleb128 (& mut self) -> Result < i64 > { leb128 :: read :: signed (self) } # [doc = " Read an initial length field."] # [doc = ""] # [doc = " This field is encoded as either a 32-bit length or"] # [doc = " a 64-bit length, and the returned `Format` indicates which."] fn read_initial_length (& mut self) -> Result < (Self :: Offset , Format) > { const MAX_DWARF_32_UNIT_LENGTH : u32 = 0xffff_fff0 ; const DWARF_64_INITIAL_UNIT_LENGTH : u32 = 0xffff_ffff ; let val = self . read_u32 () ? ; if val < MAX_DWARF_32_UNIT_LENGTH { Ok ((Self :: Offset :: from_u32 (val) , Format :: Dwarf32)) } else if val == DWARF_64_INITIAL_UNIT_LENGTH { let val = self . read_u64 () . and_then (Self :: Offset :: from_u64) ? ; Ok ((val , Format :: Dwarf64)) } else { Err (Error :: UnknownReservedLength) } } # [doc = " Read a byte and validate it as an address size."] fn read_address_size (& mut self) -> Result < u8 > { let size = self . read_u8 () ? ; match size { 1 | 2 | 4 | 8 => Ok (size) , _ => Err (Error :: UnsupportedAddressSize (size)) , } } # [doc = " Read an address-sized integer, and return it as a `u64`."] fn read_address (& mut self , address_size : u8) -> Result < u64 > { match address_size { 1 => self . read_u8 () . map (u64 :: from) , 2 => self . read_u16 () . map (u64 :: from) , 4 => self . read_u32 () . map (u64 :: from) , 8 => self . read_u64 () , otherwise => Err (Error :: UnsupportedAddressSize (otherwise)) , } } # [doc = " Parse a word-sized integer according to the DWARF format."] # [doc = ""] # [doc = " These are always used to encode section offsets or lengths,"] # [doc = " and so have a type of `Self::Offset`."] fn read_word (& mut self , format : Format) -> Result < Self :: Offset > { match format { Format :: Dwarf32 => self . read_u32 () . map (Self :: Offset :: from_u32) , Format :: Dwarf64 => self . read_u64 () . and_then (Self :: Offset :: from_u64) , } } # [doc = " Parse a word-sized section length according to the DWARF format."] # [inline] fn read_length (& mut self , format : Format) -> Result < Self :: Offset > { self . read_word (format) } # [doc = " Parse a word-sized section offset according to the DWARF format."] # [inline] fn read_offset (& mut self , format : Format) -> Result < Self :: Offset > { self . read_word (format) } # [doc = " Parse a section offset of the given size."] # [doc = ""] # [doc = " This is used for `DW_FORM_ref_addr` values in DWARF version 2."] fn read_sized_offset (& mut self , size : u8) -> Result < Self :: Offset > { match size { 1 => self . read_u8 () . map (u64 :: from) , 2 => self . read_u16 () . map (u64 :: from) , 4 => self . read_u32 () . map (u64 :: from) , 8 => self . read_u64 () , otherwise => Err (Error :: UnsupportedOffsetSize (otherwise)) , } . and_then (Self :: Offset :: from_u64) } }
    };
}

Reader!()